  async function hashPin(pin,salt){try{const bytes=new TextEncoder().encode(`${salt}:${pin}:endless-local`);const digest=await crypto.subtle.digest("SHA-256",bytes);return [...new Uint8Array(digest)].map((byte)=>byte.toString(16).padStart(2,"0")).join("");}catch{let hash=2166136261;for(const char of `${salt}:${pin}:endless-local`){hash^=char.charCodeAt(0);hash=Math.imul(hash,16777619);}return `fallback-${(hash>>>0).toString(16)}`;}}
  async function ensureTestAccount(){let account=state.accountStore.accounts.find((item)=>item.id===TEST_ACCOUNT_ID);if(!account){account={id:TEST_ACCOUNT_ID,name:TEST_ACCOUNT_NAME,createdAt:Date.now(),lastLoginAt:0,best:{wave:25,score:0},progress:{maxClearedWave:25,totalBountyRewards:0},run:null,isTest:true};state.accountStore.accounts.push(account);}account.name=TEST_ACCOUNT_NAME;account.isTest=true;account.pinHash=await hashPin("1111",account.id);account.best||={wave:25,score:0};account.progress||={maxClearedWave:25,totalBountyRewards:0};account.progress.maxClearedWave=Math.max(25,account.progress.maxClearedWave||0);persistAccountStore();}
