  async function loginSelectedAccount(){const account=state.accountStore.accounts.find((item)=>item.id===state.pendingAccountId),pin=$("#loginPin").value.trim();if(!account||!/^\d{4}$/.test(pin)){$("#loginMessage").textContent="请输入 4 位数字口令";return;}const digest=await hashPin(pin,account.id);if(digest!==account.pinHash){$("#loginMessage").textContent="口令不正确";return;}state.authenticated=true;state.accountStore.currentId=account.id;account.lastLoginAt=Date.now();account.best||={wave:0,score:0};ensureProgress(account);state.best={...account.best};persistAccountStore();$("#accountOverlay").classList.remove("show");updateAccountUI();showStartScreen();playSound("card");}
