  function loadRunCards(run){const entries=run.cards||[],cards=new Map(entries.filter(([id])=>CARD_MAP[id]&&!LEGACY_FIREPOWER_CARD_IDS.has(id)).map(([id,rank])=>[id,Math.min(CARD_MAP[id].max,Math.max(0,Math.floor(Number(rank)||0)))])),legacy=run.shop||{};let firepowerRank=entries.reduce((sum,[id,rank])=>sum+(LEGACY_FIREPOWER_CARD_IDS.has(id)?Math.max(0,Math.floor(Number(rank)||0)):0),0);firepowerRank+=Math.max(0,Math.floor(Number(legacy.damage)||0))+Math.max(0,Math.floor(Number(legacy.rate)||0));if(firepowerRank)cards.set("global_damage",Math.min(CARD_MAP.global_damage.max,firepowerRank));for(const [legacyId,cardId] of [["crit","crit_training"],["critDamage","critical_payload"]]){const level=Math.max(0,Math.floor(Number(legacy[legacyId])||0)),card=CARD_MAP[cardId];if(level&&card)cards.set(cardId,Math.min(card.max,Math.max(cards.get(cardId)||0,level)));}return cards;}

