  function triggerStellarRadiation(enemy){const boss=enemy.type.bossKind==="star",damage=Math.max(1.5,enemy.type.damage*(boss?.24:.12)*enemyAttackScale(enemy)),maxR=Math.hypot(W,H);damageCore(damage,"恒星辐射",enemy.x);for(const mini of state.miniTurrets)if(!mini.dead)damageMiniTurret(mini,damage*(boss?.72:.5));for(const turret of Object.values(state.turrets))if(turret.active)spawnSparks(turret.x,turret.y,enemy.type.color,2,34);state.particles.push({type:"stellarRadiation",x:enemy.x,y:enemy.y,r:enemyRadius(enemy)*.7,maxR,life:1.05,maxLife:1.05,color:enemy.type.color});if(boss)showToast(`威胁 ${enemyThreatTier(enemy)} · 恒星辐射 -${formatCompactNumber(damage)}`);}
  function updateStellarRadiation(enemy,dt){enemy.radiationTimer=(enemy.radiationTimer||0)-dt;if(enemy.radiationTimer>0)return;triggerStellarRadiation(enemy);const tier=enemyThreatTier(enemy);enemy.radiationTimer=enemy.type.bossKind==="star"?Math.max(5.2,9.8-(tier-1)*.38):Math.max(7.2,10.8-(tier-1)*.32);}
  function attackMiniIfReady(enemy,mini,dt){enemy.attackTimer-=dt;if(enemy.attackTimer>0)return;const tier=enemyThreatTier(enemy);enemy.attackTimer=Math.max(.72,(enemy.type.ranged?1.55:1.05)/(1+Math.min(.38,(tier-1)*.045)));damageMiniTurret(mini,Math.max(3,enemy.type.damage*.8*enemyAttackScale(enemy)));state.beams.push({x1:enemy.x,y1:enemy.y,x2:mini.x,y2:mini.y,color:COLORS.danger,life:.14,maxLife:.14,style:enemy.type.ranged?"laser":"lightning"});}
  function wanderBounty(enemy,dt,slowed){enemy.wanderTimer=(enemy.wanderTimer||0)-dt;const distance=Math.hypot(enemy.wanderX-enemy.x,enemy.wanderY-enemy.y);if(enemy.wanderTimer<=0||distance<18){enemy.wanderX=72+Math.random()*(W-144);enemy.wanderY=150+Math.random()*470;enemy.wanderTimer=1.4+Math.random()*2.1;}const dx=enemy.wanderX-enemy.x,dy=enemy.wanderY-enemy.y,length=Math.hypot(dx,dy)||1,step=enemy.speed*.72*slowed*dt;enemy.x=clamp(enemy.x+dx/length*step,45,W-45);enemy.y=clamp(enemy.y+dy/length*step,80,660);}
  function canAnyTurretReach(enemy){return Object.values(state.turrets).some((turret)=>turret.active&&turret.id!=="support"&&Math.hypot(enemy.x-turret.x,enemy.y-turret.y)<=turretRange(turret));}
  function updateEnemies(dt){
    for(const enemy of state.enemies){
      if(enemy.dead)continue;
      enemy.hit=Math.max(0,enemy.hit-dt);enemy.numberCooldown=Math.max(0,(enemy.numberCooldown||0)-dt);enemy.burnDisplayTimer=Math.max(0,(enemy.burnDisplayTimer||0)-dt);enemy.invulnerable=Math.max(0,(enemy.invulnerable||0)-dt);
      enemy.slow=Math.max(0,enemy.slow-dt);enemy.stun=Math.max(0,enemy.stun-dt);enemy.iceFracture=Math.max(0,(enemy.iceFracture||0)-dt);enemy.fireFracture=Math.max(0,(enemy.fireFracture||0)-dt);enemy.fractureLock=Math.max(0,(enemy.fractureLock||0)-dt);
      enemy.vulnerableTime=Math.max(0,enemy.vulnerableTime-dt);if(!enemy.vulnerableTime){enemy.vulnerable=0;enemy.vulnerabilitySources={};}if(enemy.bountyTime>0)enemy.bountyTime=Math.max(0,enemy.bountyTime-dt);
      if(enemy.burn>0){enemy.burn-=dt;damageEnemy(enemy,enemy.burnDps*dt,"燃烧");if((enemy.burnDisplayTimer<=0||enemy.dead)&&enemy.burnDisplay>0){addParticleText(enemy.x,enemy.y-10,`-${formatCompactNumber(Math.max(1,enemy.burnDisplay))}`,COLORS.missile);enemy.burnDisplay=0;enemy.burnDisplayTimer=.32;}if(enemy.dead)continue;}
      if(enemy.typeId==="bh_asteroid"){updateEjectedAsteroid(enemy,dt);continue;}
      if(resolveBarrierCollision(enemy)&&enemy.dead)continue;

      // 黑洞首领不响应电离诱引、子炮塔嘲讽或控制，只会以自身缓慢速度持续推进。
      if(enemy.type.bossKind==="blackhole"){
        updateBlackHoleGamma(enemy,dt);
        updateBlackHoleAsteroids(enemy,dt);
        const radius=enemyRadius(enemy),minX=Math.min(radius,W/2),maxX=Math.max(W-radius,W/2);
        enemy.y+=enemy.speed*blackHoleMoveScale(enemy)*dt;
        enemy.x+=Math.sin(state.elapsed*.22+enemy.phase)*enemy.drift*dt;
        enemy.x=clamp(enemy.x,minX,maxX);
        if(enemy.y>=CORE_Y){enemy.dead=true;state.waveResolved+=1;damageCore(enemy.type.damage*enemyAttackScale(enemy),"黑洞突破",enemy.x);}
        continue;
      }

      // 恒星作为中途小首领，免疫减速、眩晕与子炮塔诱引，只沿固定航线缓慢推进。
      if(enemy.type.bossKind==="star"){
        updateStellarRadiation(enemy,dt);
        const radius=enemyRadius(enemy),minX=Math.min(radius,W/2),maxX=Math.max(W-radius,W/2);
        enemy.y+=enemy.speed*dt;
        enemy.x+=Math.sin(state.elapsed*.34+enemy.phase)*enemy.drift*.35*dt;
        enemy.x=clamp(enemy.x,minX,maxX);
        if(enemy.y>=CORE_Y){enemy.dead=true;state.waveResolved+=1;damageCore(enemy.type.damage*enemyAttackScale(enemy),"恒星突破",enemy.x);}
        continue;
      }

      if(enemy.stun>0)continue;
      if(enemy.typeId==="nova")updateStellarRadiation(enemy,dt);else updateEnemyGun(enemy,dt);
      const slowed=enemy.slow>0?1-enemy.slowPower:1;
      const minis=state.miniTurrets.filter((item)=>!item.dead).map((mini)=>({mini,distance:Math.hypot(mini.x-enemy.x,mini.y-enemy.y)})).sort((a,b)=>a.distance-b.distance);
      const nearest=minis[0],lureRank=cardRank("mini_lure"),lureRadius=lureRank?90+lureRank*45:0,attackRange=enemy.type.ranged?220:enemyRadius(enemy)+13;
      if(nearest&&lureRank&&nearest.distance<=lureRadius){const dx=nearest.mini.x-enemy.x,dy=nearest.mini.y-enemy.y,length=nearest.distance||1;if(nearest.distance>attackRange){const step=enemy.speed*slowed*dt;enemy.x=clamp(enemy.x+dx/length*step,28,W-28);enemy.y+=dy/length*step;}else attackMiniIfReady(enemy,nearest.mini,dt);continue;}
      if(nearest&&nearest.distance<=attackRange){attackMiniIfReady(enemy,nearest.mini,dt);continue;}
      if(enemy.type.bounty&&enemy.bountyTime>0){wanderBounty(enemy,dt,slowed);continue;}
      if(enemy.type.ranged&&enemy.y>=enemy.stopY&&canAnyTurretReach(enemy))continue;
      enemy.y+=enemy.speed*slowed*dt;enemy.x+=Math.sin(state.elapsed*1.1+enemy.phase)*enemy.drift*dt;enemy.x=clamp(enemy.x,35,W-35);
      if(enemy.y>=CORE_Y){enemy.dead=true;state.waveResolved+=1;damageCore(enemy.type.damage*enemyAttackScale(enemy),"突破伤害",enemy.x);}
    }
    state.enemies=state.enemies.filter((enemy)=>!enemy.dead);
  }
  function updateDefense(dt){updateRepairBots(dt);const regen=cardRank("shield_regen");if(regen&&state.shield<state.shieldMax&&state.elapsed-state.lastDamageTime>4)gainShield((.5+regen*1.5)*dt,"护盾再生");}
  function spawnSparks(x,y,color,count=6,force=80){for(let i=0;i<count;i++){const angle=Math.random()*TAU,speed=force*(.35+Math.random()*.8);state.particles.push({type:"spark",x,y,vx:Math.cos(angle)*speed,vy:Math.sin(angle)*speed,size:1+Math.random()*2.4,color,life:.22+Math.random()*.28,maxLife:.5});}}
  function updateEffects(dt){for(const beam of state.beams)beam.life-=dt;state.beams=state.beams.filter((beam)=>beam.life>0);for(const field of state.slowFields){field.life-=dt;for(const enemy of state.enemies)if(!enemy.dead&&Math.hypot(enemy.x-field.x,enemy.y-field.y)<=field.radius)applySlow(enemy,field.power,.22);}state.slowFields=state.slowFields.filter((field)=>field.life>0).slice(-12);for(const particle of state.particles){if(particle.realTime)continue;particle.life-=dt;if(particle.type==="text")particle.y-=34*dt;else if(particle.type==="spark"){particle.x+=particle.vx*dt;particle.y+=particle.vy*dt;particle.vx*=Math.pow(.06,dt);particle.vy=particle.vy*Math.pow(.09,dt)+70*dt;}}state.particles=state.particles.filter((particle)=>particle.life>0).slice(-360);}
  function updateRealtimeEffects(now){let hasExpired=false;for(const particle of state.particles){if(!particle.realTime)continue;const duration=Math.max(.01,particle.realDuration||particle.maxLife||1.6),elapsed=Math.max(0,(now-(particle.realStartedAt||now))/1000);particle.life=Math.max(0,duration-elapsed);particle.maxLife=duration;if(particle.life<=0)hasExpired=true;}if(hasExpired)state.particles=state.particles.filter((particle)=>particle.life>0);}
