    ctx.shadowColor=color;ctx.shadowBlur=active?26:5;for(const layer of [{o:-5,w:16,a:.07},{o:0,w:9,a:.16},{o:5,w:4,a:.68},{o:9,w:1.5,a:1}]){domePath(layer.o);ctx.strokeStyle=layer.o===9?(active?"rgba(235,254,255,.9)":"rgba(184,192,197,.55)"):color;ctx.lineWidth=layer.w;ctx.globalAlpha=layer.a*(active?(.62+.38*ratio):.52);ctx.stroke();}
